INSERT INTO RULE_DEPLOY (
DEPLOY_DATETIME
, RULEID
, RULE_VERNO
, RULE_UPDATE_YN
, BEFORE_DEPLOY_APPLY_YN
, AFTER_DEPLOY_APPLY_YN
, RULE_UPDATE_USERID
, RULE_UPDATE_DATETIME
, REG_USERID
, REG_DATETIME
) VALUES (
(
SELECT TO_CHAR(DEPLOY_DATETIME, 'YYYYMMDDHH24MISS')
FROM RULE
WHERE RULEID = #{ruleid}
)
, #{ruleid}
, #{ruleVerno}
, #{ruleUpdateYn}
, #{beforeDeployApplyYn}
, #{afterDeployApplyYn}
, #{ruleUpdateUserid}
, #{ruleUpdateDatetime}
, #{regUserid}
, TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
)
